// Package spec holds the Minecraft knowledge MMS compiles against: the
// vanilla-mcdoc type table filtered to one game version, plus registries,
// block states and the command tree. The data is generated by specgen and
// embedded; see docs/decisions.md D3 for why it keeps mcdoc's own shape.
package spec

import (
	"encoding/json"
	"strings"
)

// Type is one mcdoc type node. Kind selects which of the other fields are
// meaningful; the field names follow the symbols.json export.
type Type struct {
	Kind       string      `json:"kind"`
	Attributes []Attribute `json:"attributes,omitempty"`

	// struct
	Fields []*Field `json:"fields,omitempty"`

	// reference
	Path string `json:"path,omitempty"`

	// list, int_array, string
	Item        *Type  `json:"item,omitempty"`
	LengthRange *Range `json:"lengthRange,omitempty"`

	// numbers
	ValueRange *Range `json:"valueRange,omitempty"`

	// union
	Members []*Type `json:"members,omitempty"`

	// dispatcher, indexed
	Registry        string   `json:"registry,omitempty"`
	ParallelIndices []*Index `json:"parallelIndices,omitempty"`

	// enum
	EnumKind string       `json:"enumKind,omitempty"`
	Values   []*EnumValue `json:"-"`

	// tree: attribute argument maps
	Tree map[string]*Type `json:"-"`

	// template, concrete, indexed
	Child      *Type       `json:"child,omitempty"`
	TypeArgs   []*Type     `json:"typeArgs,omitempty"`
	TypeParams []TypeParam `json:"typeParams,omitempty"`

	// tuple
	Items []*Type `json:"items,omitempty"`

	// literal: the literal's own value; static: a string such as "%fallback"
	Literal *Literal `json:"-"`
	Static  string   `json:"-"`

	// dynamic
	Accessor []json.RawMessage `json:"accessor,omitempty"`
}

// Field is a struct member: a key/value pair or a spread of another type.
type Field struct {
	Kind       string      `json:"kind"` // "pair" or "spread"
	Attributes []Attribute `json:"attributes,omitempty"`
	Desc       string      `json:"desc,omitempty"`
	Optional   bool        `json:"optional,omitempty"`
	// Key is the field name for a fixed key. KeyType is set instead for
	// computed keys such as `[#[id="block"] string]: ...`.
	Key     string `json:"-"`
	KeyType *Type  `json:"-"`
	Type    *Type  `json:"type"`
}

type Attribute struct {
	Name  string `json:"name"`
	Value *Type  `json:"value,omitempty"`
}

type Range struct {
	// Kind is a bit set: 1 means min is exclusive, 2 means max is exclusive.
	Kind int      `json:"kind"`
	Min  *float64 `json:"min,omitempty"`
	Max  *float64 `json:"max,omitempty"`
}

type Index struct {
	Kind     string            `json:"kind"` // "static" or "dynamic"
	Value    string            `json:"value,omitempty"`
	Accessor []json.RawMessage `json:"accessor,omitempty"`
}

type EnumValue struct {
	Identifier string          `json:"identifier"`
	Value      json.RawMessage `json:"value"`
	Desc       string          `json:"desc,omitempty"`
	Attributes []Attribute     `json:"attributes,omitempty"`
}

// String returns the enum value as a string, for string enums.
func (e *EnumValue) String() string {
	var s string
	if json.Unmarshal(e.Value, &s) == nil {
		return s
	}
	return strings.TrimSpace(string(e.Value))
}

type TypeParam struct {
	Path string `json:"path"`
}

// Literal is a literal value with its own kind (string, boolean, int,
// float, ...), as used by literal types and attribute arguments.
type Literal struct {
	Kind  string          `json:"kind"`
	Value json.RawMessage `json:"value"`
}

// String returns the literal as a string when it is one.
func (l *Literal) String() string {
	var s string
	if json.Unmarshal(l.Value, &s) == nil {
		return s
	}
	return string(l.Value)
}

// Attr returns the first attribute with the given name.
func (t *Type) Attr(name string) (Attribute, bool) {
	if t == nil {
		return Attribute{}, false
	}
	return findAttr(t.Attributes, name)
}

func (f *Field) Attr(name string) (Attribute, bool) { return findAttr(f.Attributes, name) }

func findAttr(as []Attribute, name string) (Attribute, bool) {
	for _, a := range as {
		if a.Name == name {
			return a, true
		}
	}
	return Attribute{}, false
}

// LiteralString returns the string inside a literal attribute value such
// as `#[since="1.21"]`.
func (a Attribute) LiteralString() (string, bool) {
	if a.Value == nil || a.Value.Kind != "literal" || a.Value.Literal == nil {
		return "", false
	}
	return a.Value.Literal.String(), true
}

// typeJSON mirrors Type for the fields whose JSON spelling depends on kind.
type typeJSON struct {
	Kind  string          `json:"kind"`
	Value json.RawMessage `json:"value,omitempty"`
	// "values" is a list for enums and a map for trees.
	Values json.RawMessage `json:"values,omitempty"`
}

type typeAlias Type

func (t *Type) UnmarshalJSON(b []byte) error {
	if err := json.Unmarshal(b, (*typeAlias)(t)); err != nil {
		return err
	}
	var extra typeJSON
	if err := json.Unmarshal(b, &extra); err != nil {
		return err
	}
	switch t.Kind {
	case "literal":
		if len(extra.Value) > 0 {
			t.Literal = &Literal{}
			if err := json.Unmarshal(extra.Value, t.Literal); err != nil {
				return err
			}
		}
	case "static":
		_ = json.Unmarshal(extra.Value, &t.Static)
	case "enum":
		if len(extra.Values) > 0 {
			if err := json.Unmarshal(extra.Values, &t.Values); err != nil {
				return err
			}
		}
	case "tree":
		if len(extra.Values) > 0 {
			if err := json.Unmarshal(extra.Values, &t.Tree); err != nil {
				return err
			}
		}
	}
	return nil
}

func (t *Type) MarshalJSON() ([]byte, error) {
	m := map[string]any{}
	b, err := json.Marshal((*typeAlias)(t))
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, err
	}
	switch t.Kind {
	case "literal":
		if t.Literal != nil {
			m["value"] = t.Literal
		}
	case "static":
		m["value"] = t.Static
	case "enum":
		m["values"] = t.Values
	case "tree":
		m["values"] = t.Tree
	}
	return json.Marshal(m)
}

type fieldAlias Field

type fieldJSON struct {
	Key json.RawMessage `json:"key,omitempty"`
}

func (f *Field) UnmarshalJSON(b []byte) error {
	if err := json.Unmarshal(b, (*fieldAlias)(f)); err != nil {
		return err
	}
	var extra fieldJSON
	if err := json.Unmarshal(b, &extra); err != nil {
		return err
	}
	if len(extra.Key) == 0 {
		return nil
	}
	if extra.Key[0] == '"' {
		return json.Unmarshal(extra.Key, &f.Key)
	}
	f.KeyType = &Type{}
	return json.Unmarshal(extra.Key, f.KeyType)
}

func (f *Field) MarshalJSON() ([]byte, error) {
	m := map[string]any{}
	b, err := json.Marshal((*fieldAlias)(f))
	if err != nil {
		return nil, err
	}
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, err
	}
	if f.KeyType != nil {
		m["key"] = f.KeyType
	} else if f.Kind == "pair" {
		m["key"] = f.Key
	}
	return json.Marshal(m)
}
